import heapq
from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Build reversed graph: original a->b becomes b->a
        graph = [[] for _ in range(n)]
        for a, b, w in edges:
