        # dist[v] = minimum over paths 0->v of (max edge weight on path)
        INF = float('inf')
        dist = [INF] * n
        dist[0] = 0
        heap = [(0, 0)]

        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                nd = w if w > d else d  # max(d, w)
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(heap, (nd, v))

        ans = 0
        for i in range(n):
            if dist[i] == INF:
