import heapq
from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        graph = [[] for _ in range(n)]
        for a, b, w in edges:
            graph[b].append((a, w))

        INF = float("inf")
        dist = [INF] * n
        dist[0] = 0
        heap = [(0, 0)]

        while heap:
            d, u = heapq.heappop(heap)
            if d != dist[u]:
                continue

            for v, w in graph[u]:
                nd = max(d, w)
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(heap, (nd, v))

        ans = max(dist)
        return -1 if ans == INF else ans
